# number of variables
n = 28
A = []
b = []

for line in equations.strip().splitlines():
    coeffs = [0]*n

    for k, idx in re.findall(r'([+-]?\d+)\*x_(\d+)', line):
        coeffs[int(idx)] = int(k)

    rhs = int(line.split('=')[1].strip())
    A.append(coeffs)
    b.append(rhs)

A = sp.Matrix(A)
b = sp.Matrix(b)

solution = A.LUsolve(b)

flag = ''.join(chr(int(round(v))) for v in solution)
print("pascalCTF{" + flag + "}")
